  const { year, month, day } = wallClock(epochMs, timeZone);
  return formatDay(year, month, day);
}

/** How far `timeZone`'s wall clock runs ahead of UTC at `epochMs`. */
function offsetMs(epochMs: number, timeZone: string): number {
  const { year, month, day, hour } = wallClock(epochMs, timeZone);
  const asUtc = Date.UTC(year, month - 1, day, hour, 0, 0);
  const { minute, second } = wallClockSeconds(epochMs, timeZone);
  return asUtc + (minute * 60 + second) * 1_000 - Math.floor(epochMs / 1_000) * 1_000 - (epochMs % 1_000 === 0 ? 0 : 0);
}

