  const asUtc = Date.UTC(year, month - 1, day, hour, 0, 0);
  const { minute, second } = wallClockSeconds(epochMs, timeZone);
  return asUtc + (minute * 60 + second) * 1_000 - Math.floor(epochMs / 1_000) * 1_000 - (epochMs % 1_000 === 0 ? 0 : 0);
}

/** The `YYYY-MM-DD` calendar date of `value` on `timeZone`'s clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  return dayOf(parseIso(value).getTime(), timeZone);
}

/** The hour, 0-23, that `instant` shows on `timeZone`'s clock. */
export function localHour(instant: Date, timeZone: string): number {
  return wallClock(instant.getTime(), timeZone).hour;
}

/**
 * The instant at which `timeZone`'s clock shows `day` at `hour`:00. Two passes
 * of the offset correct for a zone whose offset differs at the guessed instant
 * (a DST change between the guess and the answer).
 */
function instantAt(day: string, hour: number, timeZone: string): number {
  const [year, month, date] = day.split("-").map(Number) as [number, number, number];
  const guess = Date.UTC(year, month - 1, date, hour);
  const first = guess - offsetMs(guess, timeZone);
  return guess - offsetMs(first, timeZone);
}

/** The instant `timeZone`'s calendar day `day` (YYYY-MM-DD) begins. */
export function localDayStart(day: string, timeZone: string): IsoTimestamp {
  return toIsoTimestamp(new Date(instantAt(day, 0, timeZone)));
}

/** The instant the calendar day containing `reference` began on `timeZone`'s clock. */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return localDayStart(dayOf(reference.getTime(), timeZone), timeZone);
}

/** Moves a `YYYY-MM-DD` calendar date by whole days. Pure calendar arithmetic. */
export function shiftLocalDay(day: string, days: number): string {
  const [year, month, date] = day.split("-").map(Number) as [number, number, number];
  const shifted = new Date(Date.UTC(year, month - 1, date + days));
  return formatDay(
    shifted.getUTCFullYear(),
    shifted.getUTCMonth() + 1,
    shifted.getUTCDate(),
  );
}

/**
 * True once the calendar day (on `timeZone`'s clock) containing `dueAt` has
 * ended. A due date is a whole day, so on that day itself it is not overdue.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < dayOf(reference.getTime(), timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The 24-hour window a digest covers, ending at today's `digestHourUtc`. If
 * that hour has not arrived yet on `reference`'s day, the window is the one
 * that ended yesterday — so a job run early never mails an empty digest and
 * then skips the real one.
 */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  const end = new Date(
    Date.UTC(
      reference.getUTCFullYear(),
      reference.getUTCMonth(),
      reference.getUTCDate(),
      digestHourUtc,
      0,
      0,
      0,
    ),
  );
  if (end.getTime() > reference.getTime()) {
    end.setUTCDate(end.getUTCDate() - 1);
  }

  return {
    start: toIsoTimestamp(new Date(end.getTime() - DAY_MS)),
    end: toIsoTimestamp(end),
  };
}

