/**
 * The window a digest covers, on `timeZone`'s clock. It ends at the most recent
 * local `digestHourUtc`:00 at or before `reference` — today's if that hour has
 * passed, yesterday's otherwise, so a job run early never mails an empty digest
 * and then skips the real one. It starts at the same local hour on the previous
 * calendar day, so across a DST change it spans 23 or 25 hours.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHour}`);
  }

  let endDay = dayOf(reference.getTime(), timeZone);
  let end = instantAt(endDay, digestHour, timeZone);
  if (end > reference.getTime()) {
    endDay = shiftLocalDay(endDay, -1);
    end = instantAt(endDay, digestHour, timeZone);
  }
  const start = instantAt(shiftLocalDay(endDay, -1), digestHour, timeZone);

  return {
    start: toIsoTimestamp(new Date(start)),
    end: toIsoTimestamp(new Date(end)),
  };
}

