  it("is overdue once the due day has ended", () => {
    expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
    expect(isOverdue(iso("2026-03-14T00:00:00.000Z"), REFERENCE)).toBe(true);
  });

  it("judges the due day on the workspace's clock", () => {
    // 12:00Z is 21:00 in Tokyo and 05:00 in Los Angeles on 15 March.
    const dueAt = iso("2026-03-14T20:00:00.000Z"); // 15 Mar 05:00 Tokyo; 14 Mar 13:00 LA
    expect(isOverdue(dueAt, REFERENCE, "Asia/Tokyo")).toBe(false);
    expect(isOverdue(dueAt, REFERENCE, "America/Los_Angeles")).toBe(true);
  });

  it("reads a local calendar date and hour in the zone", () => {
    expect(localDate(iso("2026-03-15T23:30:00.000Z"), "UTC")).toBe("2026-03-15");
    expect(localDate(iso("2026-03-15T23:30:00.000Z"), "Asia/Tokyo")).toBe("2026-03-16");
    expect(localHour(REFERENCE, "Asia/Tokyo")).toBe(21);
  });

  it("finds where the zone's day begins as a UTC instant", () => {
    expect(startOfLocalDay(REFERENCE, "UTC")).toBe("2026-03-15T00:00:00.000Z");
    expect(startOfLocalDay(REFERENCE, "Asia/Tokyo")).toBe("2026-03-14T15:00:00.000Z");
    expect(localDayStart("2026-03-15", "America/New_York")).toBe("2026-03-15T04:00:00.000Z");
  });

  it("shifts calendar dates by whole days across month boundaries", () => {
    expect(shiftLocalDay("2026-03-01", -1)).toBe("2026-02-28");
    expect(shiftLocalDay("2026-03-15", -30)).toBe("2026-02-13");
  });

  it("rejects a zone name Intl does not recognise", () => {
    expect(() => assertTimeZone("Mars/Olympus_Mons")).toThrow(RangeError);
    expect(() => assertTimeZone("Asia/Tokyo")).not.toThrow();
  });

  it("adds and subtracts whole days", () => {
    expect(addDays(iso("2026-03-15T12:00:00.000Z"), 3)).toBe("2026-03-18T12:00:00.000Z");
    expect(addDays(iso("2026-03-01T12:00:00.000Z"), -1)).toBe("2026-02-28T12:00:00.000Z");
  });

  it("ends the digest window at today's digest hour once it has passed", () => {
    const window = digestWindow(8, REFERENCE);
    expect(window.end).toBe("2026-03-15T08:00:00.000Z");
    expect(window.start).toBe("2026-03-14T08:00:00.000Z");
  });

  it("falls back to yesterday's window when the digest hour has not arrived", () => {
    const window = digestWindow(20, REFERENCE);
    expect(window.end).toBe("2026-03-14T20:00:00.000Z");
    expect(window.start).toBe("2026-03-13T20:00:00.000Z");
  });

  it("rejects a digest hour outside 0-23", () => {
    expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
    expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
  });
});

/** Relative formatting, overdue detection and the digest window. */
import { describe, expect, it } from "vitest";
import {
  addDays,
  assertTimeZone,
  digestWindow,
  formatDate,
  formatRelative,
  isOverdue,
  localDate,
  localDayStart,
  localHour,
  now,
  parseIso,
  shiftLocalDay,
  startOfLocalDay,
} from "@/lib/date";
import type { IsoTimestamp } from "@/types/common";

const REFERENCE = new Date("2026-03-15T12:00:00.000Z");
const iso = (value: string): IsoTimestamp => value as IsoTimestamp;

describe("lib/date", () => {
  it("round-trips now() through parseIso()", () => {
    const stamp = now();
    expect(parseIso(stamp).toISOString()).toBe(stamp);
  });

  it("throws on a malformed timestamp rather than yielding Invalid Date", () => {
    expect(() => parseIso(iso("not-a-date"))).toThrow(RangeError);
  });

  it("formats past distances with an 'ago' suffix", () => {
    expect(formatRelative(iso("2026-03-15T11:59:30.000Z"), REFERENCE)).toBe("just now");
    expect(formatRelative(iso("2026-03-15T11:55:00.000Z"), REFERENCE)).toBe("5 minutes ago");
    expect(formatRelative(iso("2026-03-15T11:00:00.000Z"), REFERENCE)).toBe("1 hour ago");
    expect(formatRelative(iso("2026-03-13T12:00:00.000Z"), REFERENCE)).toBe("2 days ago");
    expect(formatRelative(iso("2026-03-01T12:00:00.000Z"), REFERENCE)).toBe("2 weeks ago");
  });

  it("formats future distances with an 'in' prefix", () => {
    expect(formatRelative(iso("2026-03-15T12:30:00.000Z"), REFERENCE)).toBe("in 30 minutes");
    expect(formatRelative(iso("2026-03-18T12:00:00.000Z"), REFERENCE)).toBe("in 3 days");
  });

  it("renders an absolute date in the requested timezone", () => {
    expect(formatDate(iso("2026-03-15T23:30:00.000Z"))).toBe("15 Mar 2026");
    expect(formatDate(iso("2026-03-15T23:30:00.000Z"), "Asia/Tokyo")).toBe("16 Mar 2026");
  });

  it("treats a null due date as never overdue", () => {
    expect(isOverdue(null, REFERENCE)).toBe(false);
  });

  it("is not overdue on the due day itself, whatever time it names", () => {
    expect(isOverdue(iso("2026-03-15T00:00:00.000Z"), REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(false);
    expect(isOverdue(iso("2026-03-15T23:59:59.000Z"), REFERENCE)).toBe(false);
  });

  it("is overdue once the due day has ended", () => {
    expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
    expect(isOverdue(iso("2026-03-14T00:00:00.000Z"), REFERENCE)).toBe(true);
  });

  it("judges the due day on the workspace's clock", () => {
    // 12:00Z is 21:00 in Tokyo and 05:00 in Los Angeles on 15 March.
    const dueAt = iso("2026-03-14T20:00:00.000Z"); // 15 Mar 05:00 Tokyo; 14 Mar 13:00 LA
    expect(isOverdue(dueAt, REFERENCE, "Asia/Tokyo")).toBe(false);
    expect(isOverdue(dueAt, REFERENCE, "America/Los_Angeles")).toBe(true);
  });

  it("reads a local calendar date and hour in the zone", () => {
    expect(localDate(iso("2026-03-15T23:30:00.000Z"), "UTC")).toBe("2026-03-15");
    expect(localDate(iso("2026-03-15T23:30:00.000Z"), "Asia/Tokyo")).toBe("2026-03-16");
    expect(localHour(REFERENCE, "Asia/Tokyo")).toBe(21);
  });

  it("finds where the zone's day begins as a UTC instant", () => {
    expect(startOfLocalDay(REFERENCE, "UTC")).toBe("2026-03-15T00:00:00.000Z");
    expect(startOfLocalDay(REFERENCE, "Asia/Tokyo")).toBe("2026-03-14T15:00:00.000Z");
    expect(localDayStart("2026-03-15", "America/New_York")).toBe("2026-03-15T04:00:00.000Z");
  });

  it("shifts calendar dates by whole days across month boundaries", () => {
    expect(shiftLocalDay("2026-03-01", -1)).toBe("2026-02-28");
    expect(shiftLocalDay("2026-03-15", -30)).toBe("2026-02-13");
  });

  it("rejects a zone name Intl does not recognise", () => {
    expect(() => assertTimeZone("Mars/Olympus_Mons")).toThrow(RangeError);
    expect(() => assertTimeZone("Asia/Tokyo")).not.toThrow();
  });

  it("adds and subtracts whole days", () => {
    expect(addDays(iso("2026-03-15T12:00:00.000Z"), 3)).toBe("2026-03-18T12:00:00.000Z");
    expect(addDays(iso("2026-03-01T12:00:00.000Z"), -1)).toBe("2026-02-28T12:00:00.000Z");
  });

  it("ends the digest window at today's digest hour once it has passed", () => {
    const window = digestWindow(8, REFERENCE);
    expect(window.end).toBe("2026-03-15T08:00:00.000Z");
    expect(window.start).toBe("2026-03-14T08:00:00.000Z");
  });

  it("falls back to yesterday's window when the digest hour has not arrived", () => {
    const window = digestWindow(20, REFERENCE);
    expect(window.end).toBe("2026-03-14T20:00:00.000Z");
    expect(window.start).toBe("2026-03-13T20:00:00.000Z");
  });

  it("ends the digest window at the workspace's local digest hour", () => {
    const window = digestWindow(8, REFERENCE, "Asia/Tokyo");
    expect(window.end).toBe("2026-03-14T23:00:00.000Z");
    expect(window.start).toBe("2026-03-12T23:00:00.000Z");
  });

  it("spans 23 hours across the spring-forward change", () => {
    const window = digestWindow(1, iso("2026-03-09T12:00:00.000Z") as unknown as Date, "America/New_York");
    expect(window.end).toBe("2026-03-09T05:00:00.000Z");
    expect(window.start).toBe("2026-03-08T06:00:00.000Z");
  });

  it("rejects a digest hour outside 0-23", () => {
    expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
    expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
  });
});

